 return <div className="accessibility-dock"><button className="accessibility-hide" aria-label="הסתרת כפתור הנגישות. ניתן להחזירו דרך מידע נוסף" onClick={()=>{if(typeof window!=='undefined'&&window.matchMedia('(max-width:760px)').matches){setOpen(false);return}localStorage.setItem('kidum-a11y-floating-v08648','hidden');setOpen(false);setVisible(false)}}>×</button><button className="accessibility-fab" aria-label="פתיחת אפשרויות נגישות" aria-expanded={open} aria-controls="kidum-accessibility-panel" onClick={()=>setOpen(v=>!v)}><img className="accessibility-approved-icon" src="/media/icons/accessibility-approved.png" alt="" aria-hidden="true"/></button>{open&&<div id="kidum-accessibility-panel" ref={panelRef} className="accessibility-panel a11y-pro-panel" role="dialog" aria-modal="false" aria-label="אפשרויות נגישות"><div className="a11y-panel-head"><span><b>אפשרויות נגישות</b><small>התאימו את התצוגה והניווט לצרכים שלכם</small></span><button type="button" onClick={()=>setOpen(false)} aria-label="סגירת אפשרויות הנגישות">×</button></div><div className="a11y-shortcut">קיצור מקלדת לפתיחה: <kbd>Alt</kbd> + <kbd>A</kbd></div><section className="a11y-section"><h3>טקסט וקריאה</h3><div className="a11y-stepper"><button type="button" onClick={()=>set('text',Math.max(-2,prefs.text-1))} disabled={prefs.text<=-2} aria-label="הקטנת טקסט">−</button><span><b>גודל טקסט</b><small>{100+prefs.text*10}%</small></span><button type="button" onClick={()=>set('text',Math.min(4,prefs.text+1))} disabled={prefs.text>=4} aria-label="הגדלת טקסט">+</button></div><div className="a11y-grid">{tile('readable','Aa','גופן קריא')}{tile('line','↕','ריווח בין שורות',()=>set('line',(prefs.line+1)%4))}{tile('word','↔','ריווח בין מילים',()=>set('word',(prefs.word+1)%4))}{tile('letter','A↔','ריווח אותיות',()=>set('letter',(prefs.letter+1)%4))}</div></section><section className="a11y-section"><h3>צבעים וניגודיות</h3><div className="a11y-grid">{tile('contrast','◐','ניגודיות גבוהה',()=>toggleExclusive('contrast'))}{tile('light','☀','ניגודיות בהירה',()=>toggleExclusive('light'))}{tile('dark','☾','מצב כהה',()=>toggleExclusive('dark'))}{tile('gray','◑','גווני אפור',()=>toggleExclusive('gray'))}</div></section><section className="a11y-section"><h3>התמצאות וניווט</h3><div className="a11y-grid">{tile('links','🔗','הדגשת קישורים')}{tile('headings','H','הדגשת כותרות')}{tile('cursor','➤','סמן מוגדל')}{tile('focus','⌨','מיקוד מקלדת')}{tile('guide','▬','מדריך קריאה')}{tile('reduce','◌','הפחתת תנועה')}</div></section><div className="a11y-panel-foot"><button type="button" onClick={reset}>↻ איפוס כל ההתאמות</button><button type="button" onClick={()=>{setOpen(false);go('accessibility')}}>הצהרת נגישות</button></div><p className="a11y-help">ההתאמות נשמרות במכשיר זה. ניתן לאפס אותן בכל עת.</p></div>}</div>
