function FloatingAssistant({screen,go}:{screen:Screen;go:(s:Screen)=>void}){const[open,setOpen]=useState(false),[min,setMin]=useState(false),[msg,setMsg]=useState(''),[chat,setChat]=useState<{q:string;a:string}[]>([]);const bodyRef=useRef<HTMLDivElement>(null);useEffect(()=>{const h=()=>{setOpen(v=>{const next=!v;if(next)setMin(false);return next})};const resetAll=()=>{setChat([]);setMsg('');setOpen(false);setMin(false)};window.addEventListener('kidum:assistant-open',h);window.addEventListener('kidum:assistant-reset',resetAll);return()=>{window.removeEventListener('kidum:assistant-open',h);window.removeEventListener('kidum:assistant-reset',resetAll)}},[]);useEffect(()=>{bodyRef.current?.scrollTo({top:bodyRef.current.scrollHeight,behavior:'smooth'})},[chat.length]);const knowledge=[
{id:'child',title:'ילדים',words:['ילד','ילדה','ילדים','הוספה','להוסיף','חדש','כרטיס','תיק','רישום'],phrases:['ילד חדש','כרטיס ילד','להוסיף ילד'],a:'כדי להוסיף ילד חדש, פתחו את אזור „ילדים” ובחרו „+ ילד חדש”. מלאו את הפרטים האישיים, המסגרת והזכאות ושמרו. לאחר השמירה אפשר להמשיך לתצפית, למבדק ולתוכנית העבודה.',target:'children' as Screen},
{id:'task',title:'משימות',words:['משימה','משימות','מטלה','מטלות','לביצוע','תזכורת','דחוף','יעד','אחראי'],phrases:['ליצור משימה','משימה חדשה','הזכר לי'],a:'כדי ליצור מטלה, פתחו „משימות” ובחרו יצירת מטלה. הגדירו תאריך יעד, עדיפות ואחראי. מטלה אינה מפגש ביומן ולכן היא מופיעה במרכז המשימות ובאזור הדורש תשומת לב.',target:'tasks' as Screen},
{id:'calendar',title:'יומן ומפגשים',words:['מפגש','מפגשים','אירוע','אירועים','יומן','פגישה','שעה','חוזר','שבועי'],phrases:['לקבוע מפגש','אירוע חדש','מפגש חוזר'],a:'כדי לקבוע מפגש, פתחו „יומן” ובחרו אירוע או מפגש. הגדירו תאריך, שעות וקשרו לילד במידת הצורך. למפגש קבוע אפשר להגדיר חזרה שבועית, דו שבועית, חודשית או מותאמת.',target:'calendar' as Screen},
{id:'team',title:'ישיבות צוות',words:['ישיבת','ישיבה','צוות','משתתפים','החלטות','מטפל','מטפלים','פרא','רפואי'],phrases:['ישיבת צוות','סיכום ישיבה','איש מקצוע'],a:'בכרטיס הילד פתחו „ישיבות צוות”. האשף כולל פרטי הישיבה והמשתתפים, תמונת מצב מקצועית, ולאחר מכן סיכום והחלטות. אפשר לבחור כמה סוגי מטפלים ולתעד סוג נוסף באופן ידני.',target:'children' as Screen},
{id:'assessment',title:'תצפיות ומבדקים',words:['מבדק','מבדקים','הערכה','אבחון','תצפית','תצפיות','ציון','מטרות'],phrases:['למלא מבדק','להוסיף תצפית','תוצאות מבדק'],a:'פתחו את כרטיס הילד ובחרו „תצפיות” או „מבדקים”. שם אפשר לתעד תצפית, למלא מבדק ולעבור מהתוצאות לבחירת מטרות ולתוכנית העבודה.',target:'children' as Screen},
{id:'doc',title:'מסמכים',words:['מסמך','מסמכים','חתימה','לחתום','קובץ','קבצים','pdf','word','העלאה','הורדה','שיתוף'],phrases:['לשלוח מסמך','להעלות מסמך','מסמך חתום'],a:'פתחו את כרטיס הילד או את „המסמכים שלי”. אפשר לפתוח מסמך, למלא ולחתום, לשמור עותק חתום, להוריד ולשתף בהתאם להרשאות.',target:'myDocuments' as Screen},
{id:'report',title:'דוחות',words:['דוח','דוחות','סיכום','הפקה','טיוטה','pdf','word'],phrases:['להפיק דוח','דוח חדש'],a:'פתחו „דוחות”, בחרו סוג דוח וילד. המערכת מרכזת את המידע המתועד לתקופה שנבחרה ומכינה טיוטה שניתן לבדוק, לערוך, לשמור ולאשר.',target:'reports' as Screen},
{id:'permission',title:'הרשאות',words:['הרשאה','הרשאות','משתמש','משתמשים','גישה','תפקיד','עריכה','מנהל'],phrases:['משתמשים והרשאות','אין הרשאה','לא יכול לערוך'],a:'הרשאות נקבעות לפי התפקיד ולפי הרשאות פרטניות. מנהלת מערכת יכולה לנהל אותן באזור „משתמשים והרשאות”. אם פעולה חסומה, בדקו קודם את תפקיד המשתמש ואת ההרשאה לילד הרלוונטי.',target:'usersAdmin' as Screen},
{id:'profile',title:'החשבון שלי',words:['פרופיל','אווטאר','תמונה','שם','צבע','חשבון'],phrases:['תמונת פרופיל','לשנות אווטאר','צבע טבעת'],a:'פתחו „החשבון שלי”. אפשר לבחור אווטאר של קידום+, להעלות תמונה, לשנות שם לתצוגה ולבחור צבע לטבעת סביב התמונה. השינוי נכנס לתוקף רק לאחר לחיצה על „שמירה”.',target:'profile' as Screen},
{id:'privacy',title:'פרטיות ואבטחה',words:['פרטיות','עוגיות','מידע','אבטחה','סיסמה','כניסה','מכשיר'],phrases:['מדיניות פרטיות','שינוי סיסמה','אבטחה וכניסה'],a:'לפרטי שימוש במידע פתחו „מדיניות פרטיות”. להגדרות סיסמה, כניסה ואבטחת החשבון פתחו „אבטחה וכניסה”.',target:'privacy' as Screen},
{id:'kido',title:'קידו ותקשורת',words:['קידו','הודעה','הודעות','תקשורת','צאט','צ׳אט','קבוצה','וואטסאפ'],phrases:['לשלוח הודעה','הודעה חדשה','קבוצת הודעות'],a:'פתחו „תקשורת” כדי להשתמש בקידו. אפשר לפתוח שיחה אישית או קבוצתית, לשלוח הודעות ולצרף קבצים בהתאם להרשאות.',target:'communications' as Screen}
];const stop=new Set(['איך','איפה','מה','אני','רוצה','צריך','צריכה','אפשר','בבקשה','של','את','עם','על','לי','זה','זאת','יש','עושים','לעשות','במערכת','בקידום','קידום']);const norm=(x:string)=>x.toLowerCase().replace(/[?.,!״"'():/\-]/g,' ').split(/\s+/).filter(w=>w&&!stop.has(w));const stem=(w:string)=>w.replace(/^(ה|ו|ב|ל|כ|מ|ש)/,'').replace(/(ים|ות|ית|ה)$/,'');const answer=(q:string)=>{const raw=q.toLowerCase();const words=norm(q);const ranked=knowledge.map(k=>{let score=0;for(const ph of k.phrases)if(raw.includes(ph))score+=9;for(const w of words){const sw=stem(w);for(const kw of k.words){const sk=stem(kw);if(w===kw)score+=5;else if(sw===sk&&sw.length>2)score+=4;else if((w.includes(kw)||kw.includes(w))&&Math.min(w.length,kw.length)>2)score+=2}}if(k.target===screen)score+=1;return{k,score}}).sort((a,b)=>b.score-a.score);const first=ranked[0],second=ranked[1];if(!first||first.score<2)return {a:`אני כאן כדי להסביר פעולות בתוך קידום+. כרגע אתם במסך „${screen==='home'?'דף הבית':screen==='children'?'ילדים':screen==='tasks'?'משימות':screen==='calendar'?'יומן':screen==='profile'?'החשבון שלי':'המערכת'}”. כתבו מה אתם מנסים לבצע, למשל הוספת ילד, יצירת מפגש, מילוי מבדק, שליחת מסמך או שינוי הרשאה, ואכוון אתכם לפי הפעולה.`,target:null as Screen|null};if(second&&first.score-second.score<2&&second.score>=4)return {a:`נראה שהשאלה יכולה להתייחס גם ל„${first.k.title}” וגם ל„${second.k.title}”. כתבו לי לאיזה מהם התכוונתם ואדריך אתכם בדיוק.`,target:null as Screen|null};return {a:first.k.a,target:first.k.target}};const send=(value?:string)=>{const q=(value??msg).trim();if(!q)return;const r=answer(q);setChat(x=>[...x,{q,a:r.a}]);setMsg('')};const reset=()=>{if(chat.length&&!window.confirm('לפתוח שיחה חדשה ולמחוק את ההתכתבות הנוכחית?'))return;setChat([]);setMsg('')};if(!open)return null;if(min)return <button className="assistant-mini-launcher" onClick={()=>setMin(false)} aria-label="פתיחת העוזר האישי" title="פתיחת עוזר AI"><Plus/></button>;return <aside className="floating-assistant" aria-label="העוזר האישי של קידום+"><header><div className="assistant-brand"><Plus/><span><b>העוזר האישי של קידום+</b><small>זמין לאורך העבודה במערכת</small></span></div><div className="assistant-head-actions"><button className="assistant-reset" onClick={reset} title="שיחה חדשה" aria-label="שיחה חדשה">↻</button><button onClick={()=>setMin(!min)} aria-label={min?'הגדלה':'מזעור'}>{min?'↗':'−'}</button><button onClick={()=>setOpen(false)} aria-label="סגירה">×</button></div></header>{!min&&<><div className="assistant-body" ref={bodyRef}>{chat.length===0&&<div className="assistant-intro"><Plus/><h3>איך אפשר לעזור?</h3><p className="assistant-intro-copy">כתבו לי במילים שלכם מה תרצו לעשות בקידום+. אכוון אתכם למסך המתאים ואסביר את הפעולה שלב אחר שלב.</p><div className="assistant-suggestions">{['איך מוסיפים ילד חדש?','איך יוצרים משימה?','איך ממלאים מבדק?','איך שולחים מסמך?'].map(x=><button key={x} onClick={()=>send(x)}>{x}</button>)}</div></div>}<div className="assistant-chat-stream">{chat.map((x,i)=><div className="assistant-turn" key={i}><p className="user-msg">{x.q}</p><p className="bot-msg">{x.a}</p></div>)}</div></div><footer><textarea value={msg} onChange={e=>setMsg(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}}} placeholder="מה תרצו לעשות במערכת?"/><button className="assistant-send" onClick={()=>send()} aria-label="שליחה"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12 20 4l-5 16-3-6-8-2Z"/><path d="m12 14 8-10"/></svg></button></footer></>}</aside>}
function LegalPage({kind}:{kind:'about'|'privacy'|'terms'|'accessibility'|'policy'}){const[active,setActive]=useState(0);const content={about:{title:'אודות קידום+',lead:'סביבת עבודה מקצועית לצוותי שילוב בגני הילדים, שמחברת בין התמונה המקצועית, התכנון, המפגשים, התיעוד, המסמכים, המשימות והתקשורת במקום אחד, סביב הילד.',sections:[['למה פיתחנו את קידום+','עבודת השילוב משלבת מידע מקצועי, תכנון, תיעוד, משימות, מסמכים ותקשורת עם גורמים שונים. כאשר כל חלק מנוהל במקום אחר, קשה לשמור על רצף עבודה ברור לאורך השנה. קידום+ פותחה כדי לרכז את התהליך המקצועי בסביבה אחת, לחבר בין שלבי העבודה ולתת לצוות תמונה עדכנית ונגישה של התהליך סביב כל ילד.'],['הילד במרכז','במרכז המערכת נמצא כרטיס הילד. ממנו מגיעים לפרטים האישיים, לזכאות ולסל, לתוכניות העבודה, לישיבות הצוות, לתצפיות, למבדקים, לתיעוד המפגשים, למשימות ולמסמכים. המטרה היא לא רק לשמור מידע, אלא להפוך אותו לעבודה מקצועית רציפה.'],['מרצף מקצועי לעבודה יומיומית','קידום+ מחברת בין היכרות ותצפית, מבדק, בחירת מטרות, בניית תוכנית שנתית, תכנון מפגשים, תיעוד ומעקב. כך אפשר לעבור מהתכנון לביצוע בלי לאבד את ההקשר המקצועי.'],['סביבה שמותאמת לתפקיד','הורים, גננות שילוב, רכזות ומנהלות מערכת מקבלים סביבת עבודה בהתאם לאחריות ולהרשאות שלהם. כל משתמש רואה את המידע והפעולות הנחוצים לעבודתו, בהתאם להרשאות שהוגדרו עבורו.'],['כלים חכמים כתמיכה בעבודה','אוטומציה ויכולות AI נועדו לחסוך זמן, לסדר מידע ולהדריך את המשתמש. הן מסייעות לעבודה, אך אינן מחליפות שיקול דעת מקצועי או החלטה של איש מקצוע.']]},privacy:{title:'מדיניות פרטיות',lead:'בקידום+ אנו מייחסים חשיבות להגנה על המידע של ילדים, משפחות ואנשי צוות. בעמוד זה מוסבר אילו סוגי מידע נשמרים לצורך הפעלת המערכת וכיצד נעשה בהם שימוש.',sections:[['המידע שנשמר במערכת','המערכת כוללת פרטי משתמש וחשבון, פרטי ילדים ומסגרות, מידע מקצועי שנכתב במסגרת העבודה, מסמכים וקבצים, משימות, מפגשים ותיעוד הנדרשים להפעלת השירות.'],['מטרות השימוש במידע','המידע משמש להפעלת קידום+, זיהוי משתמשים, ניהול הרשאות, ביצוע תהליכי העבודה המקצועיים, שמירת רצף תיעודי, אבטחת המערכת ומתן תמיכה.'],['מידע על ילדים ומשפחות','מידע הנוגע לילדים ולמשפחות מוצג ונערך בהתאם לתפקיד ולהרשאות המשתמש. יש להשתמש בו רק לצורך העבודה המורשית ולשמור על סודיותו.'],['מסמכים והעלאות','מסמכים, תמונות וקבצים שמועלים למערכת נשמרים כחלק מתהליך העבודה ובהתאם להרשאות. המשתמש אחראי לוודא שהעלאת הקובץ נדרשת לצורך עבודתו ושיש לו הרשאה מתאימה.'],['אחסון בדפדפן','המערכת משתמשת באחסון בדפדפן לצרכים תפעוליים כגון מצב התחברות, העדפות תצוגה והגדרות ממשק. אין בדף זה הצהרה על כלי שיווק או מדידה שאינם פעילים בפועל במערכת.'],['גישה והרשאות','הגישה למידע נקבעת לפי תפקיד והרשאות. משתמשים נדרשים לשמור על סודיות פרטי הכניסה ולהימנע מהעברת מידע למי שאינו מורשה לקבלו.'],['שמירה, עדכון ופנייה','לשאלות הנוגעות למידע אישי, לעדכון פרטים או לבקשה הנוגעת לפרטיות ניתן לפנות למנהלת המערכת. הטיפול נעשה בהתאם לסוג המידע, להרשאות ולחובות החלות על הארגון.']]},terms:{title:'תנאי שימוש',lead:'השימוש בקידום+ מיועד למשתמשים מורשים לצורך עבודה מקצועית ובהתאם לתפקיד ולהרשאות שניתנו להם. שימוש במערכת כפוף לכללים המפורטים בעמוד זה.',sections:[['חשבון אישי והרשאות','החשבון הוא אישי. אין להעביר סיסמה או אמצעי גישה לאחר. כל משתמש אחראי לשימוש שנעשה באמצעות חשבונו ולשמירה על פרטי הכניסה.'],['שימוש מקצועי במערכת','יש להשתמש במידע ובכלים של קידום+ רק לצורך העבודה המורשית. אין לעיין, להעתיק, להעביר או לשתף מידע של ילד, משפחה או איש צוות ללא הרשאה מתאימה.'],['תוכן, מסמכים ותמונות','המשתמש אחראי למידע, למסמכים, לתמונות ולהודעות שהוא מזין או משתף. אין להעלות תוכן שאינו נדרש לעבודה או שאין הרשאה לשמור אותו במערכת.'],['תקשורת בקידו','כלי התקשורת נועד לעבודה הקשורה למערכת ולתהליך המקצועי. יש להקפיד על שיח ענייני, שמירה על פרטיות והימנעות משיתוף מידע עם גורם שאינו מורשה.'],['יכולות AI ואוטומציה','כלים חכמים במערכת נועדו לסייע בארגון מידע, ניסוח והדרכה. יש לבדוק את התוצר לפני שימוש מקצועי. תוצר אוטומטי אינו תחליף לשיקול דעת מקצועי.'],['שימושים שאינם מותרים','אין לנסות לעקוף הרשאות, לגשת למידע ללא סמכות, לשבש את פעילות המערכת, להשתמש בחשבון של אדם אחר או לעשות שימוש במידע בניגוד למטרת המערכת.'],['זמינות ושינויים בשירות','קידום+ מתפתחת באופן שוטף. ייתכנו עדכונים, עבודות תחזוקה ושינויים בממשק או בפונקציות. נעשה מאמץ לשמור על רציפות השירות ועל המידע באמצעות המנגנונים הקיימים במערכת.'],['קניין רוחני','העיצוב, המיתוג, התוכנה והתכנים המקוריים של קידום+ מוגנים לפי הדין. אין להעתיק או לעשות בהם שימוש מסחרי ללא הרשאה.'],['פרטיות ואבטחת מידע','השימוש במידע כפוף למדיניות הפרטיות של קידום+ ולהרשאות שהוגדרו במערכת. המשתמש נדרש לדווח על חשש לחשיפה או שימוש לא מורשה בחשבון או במידע.'],['הפסקת שימוש ועדכון התנאים','הרשאה למערכת יכולה להשתנות או להיפסק בהתאם לתפקיד, להרשאות ולמדיניות הארגון. תנאי השימוש עשויים להתעדכן כאשר משתנים השירותים או אופן העבודה במערכת.']]},policy:{title:'מדיניות השימוש במערכת',lead:'מדיניות זו מרכזת את כללי העבודה המקצועית בקידום+ ומבהירה כיצד נכון להשתמש במערכת, במידע ובכלי התקשורת במסגרת התפקיד.',sections:[['מטרת המערכת','קידום+ מיועדת לניהול העבודה המקצועית סביב תהליכי שילוב בגני הילדים. יש להשתמש במערכת לצורכי התפקיד ובהתאם להרשאות שניתנו לכל משתמש.'],['אחריות המשתמש','כל משתמש אחראי לשמור על פרטי הכניסה שלו, לעבוד מחשבון אישי בלבד ולוודא שמידע מוזן, נצפה ומשותף רק כאשר הדבר נדרש לצורך העבודה.'],['תיעוד מקצועי','יש להקפיד על תיעוד ענייני, מדויק ומכבד. מידע מקצועי, סיכומי מפגשים, מבדקים, מסמכים והודעות צריכים להיות קשורים ישירות לתהליך העבודה ולילד הרלוונטי.'],['שיתוף ותקשורת','שיתוף מידע ומסמכים יתבצע רק עם גורמים מורשים ובאמצעות הכלים שהוגדרו במערכת. לפני שליחה יש לוודא שהנמען והמסמך נכונים.'],['כלים חכמים ואוטומציה','הכלים החכמים בקידום+ נועדו לסייע בהתמצאות, בארגון ובניסוח. האחריות לבדיקה ולאישור של תוכן מקצועי נשארת בידי איש המקצוע.'],['דיווח על תקלה או חשש','במקרה של תקלה, גישה חריגה, חשש לחשיפת מידע או פעולה שאינה תואמת את ההרשאה, יש להפסיק את הפעולה ולפנות למנהלת המערכת.']]},accessibility:{title:'הצהרת נגישות',lead:'קידום+ פועלת לשפר את נגישות המערכת ולאפשר שימוש נוח וברור ככל האפשר למשתמשים עם צרכים שונים. הנגישות היא חלק מתכנון הממשק ולא רק תפריט עזר.',sections:[['התאמות בממשק','המערכת כוללת מבנה RTL, היררכיית כותרות, תוויות לשדות, מצבי מיקוד וניסיון לאפשר הפעלה באמצעות מקלדת באזורים המרכזיים. התאמות נוספות נבדקות כחלק מהפיתוח השוטף.'],['כלי הנגישות של קידום+','כפתור הנגישות מאפשר הגדלה והקטנה של טקסט, ניגודיות גבוהה, מצב כהה, הפחתת תנועה, גופן קריא, הדגשת קישורים ואיפוס ההתאמות.'],['שימוש במקלדת','אנו פועלים לשיפור סדר המיקוד, הפעלת פקדים באמצעות מקלדת ומיקוד ברור ברכיב הפעיל.'],['קוראי מסך וטכנולוגיות מסייעות','ברכיבים מרכזיים נעשה שימוש בשמות נגישים, תוויות ומבנה סמנטי. חלונות ותפריטים ממשיכים לעבור בדיקות ושיפורים כדי לשפר את התאימות לטכנולוגיות מסייעות.'],['תנועה ותצוגה','כלי הנגישות מאפשר להפחית תנועה ואנימציות ולבצע התאמות תצוגה. המערכת מתוכננת גם להתאמה למסכים בגדלים שונים.'],['טפסים והודעות','אנו פועלים להצגת תוויות ברורות לשדות, הודעות שגיאה מובנות ומיקוד מתאים בעת פתיחת חלונות ותהליכים.'],['מסמכים וקבצים','חלק מהמסמכים במערכת מועלים על ידי המשתמשים או נוצרים ממקורות שונים. ייתכן שמסמך מסוים ידרוש התאמת נגישות נוספת.'],['נתקלתם בקושי?','אם נתקלתם בבעיה, פנו לתמיכת המערכת וציינו באיזה מסך הייתם, מה ניסיתם לבצע ומה הייתה הבעיה. הפרטים יסייעו לנו לבדוק ולשפר את החוויה.']]}} as const;const d=content[kind];const jump=(i:number)=>{setActive(i);const el=document.getElementById(`legal-${kind}-${i}`);el?.scrollIntoView({behavior:'smooth',block:'center'});if(el){el.classList.remove('legal-section-focus');void el.offsetWidth;el.classList.add('legal-section-focus');window.setTimeout(()=>el.classList.remove('legal-section-focus'),1800)}};return <main className={`legal-page legal-${kind}`}><section className="legal-hero"><span className="eyebrow">קידום+</span><h1>{d.title}</h1><p>{d.lead}</p>{kind==='about'&&<strong>כל ילד. הדרך שלו.</strong>}<small>עודכן לאחרונה: אוקטובר 2026</small></section>{kind==='about'&&<section className="legal-values"><article><UiIcon name="children"/><b>תמונה מקצועית אחת</b><span>כל המידע החשוב סביב הילד במקום אחד.</span></article><article><UiIcon name="target"/><b>מתכנון לביצוע</b><span>ממבדק ומטרות ועד מפגשים ומשימות.</span></article><article><UiIcon name="chart"/><b>מעקב רציף</b><span>רואים מה נעשה ומה דורש המשך טיפול.</span></article><article><UiIcon name="heart"/><b>עבודה משותפת</b><span>חיבור בין הצוות, הרכזת והמשפחה לפי הרשאות.</span></article></section>}<section className="legal-layout"><nav className="legal-toc" aria-label="ניווט בתוך העמוד"><b>בעמוד זה</b>{d.sections.map((x,i)=><button type="button" className={active===i?'active':''} key={i} onClick={()=>jump(i)}>{x[0]}</button>)}</nav><div className="legal-sections">{d.sections.map((x,i)=><article id={`legal-${kind}-${i}`} key={i}><span className="legal-section-icon"><UiIcon name={kind==='privacy'?'security':kind==='accessibility'?'heart':kind==='terms'||kind==='policy'?'doc':'sparkle'} size={20}/></span><div><h2>{x[0]}</h2><p>{x[1]}</p></div></article>)}</div></section>{kind==='about'&&<section className="about-flow"><h2>רצף עבודה שמחבר את כל התמונה</h2><div>{['היכרות','תצפית','מבדק','מטרות','תוכנית שנתית','מפגשים','תיעוד','מעקב'].map((x,i)=><span key={x}><b>{i+1}</b>{x}</span>)}</div></section>}<section className="legal-note"><UiIcon name={kind==='about'?'target':kind==='accessibility'?'heart':'security'} size={24}/><div><b>{kind==='about'?'החזון שלנו':kind==='privacy'?'פרטיות היא חלק מהמערכת':kind==='policy'?'עבודה מקצועית ואחראית':kind==='terms'?'חשוב לדעת':'הנגישות ממשיכה להשתפר'}</b><p>{kind==='about'?'לאפשר לצוותים לראות את התמונה המלאה, לעבוד בצורה מסודרת ורציפה ולתת לכל ילד תהליך מקצועי שמתאים לדרך שלו.':kind==='privacy'?'המדיניות נועדה לשקף את אופן העבודה בפועל. ככל שיתווספו שירותים שמשנים את אופן השימוש במידע, העמוד יעודכן בהתאם.':kind==='policy'?'המדיניות משלימה את תנאי השימוש ואת מדיניות הפרטיות ומטרתה ליצור כללי עבודה ברורים ועקביים לכל המשתמשים.':kind==='terms'?'תנאים אלה אינם גורעים מחובות סודיות, פרטיות או הוראות אחרות החלות על המשתמש במסגרת תפקידו.':'כפתור הנגישות הוא כלי עזר. אנו ממשיכים לטפל גם בנגישות המבנית של המסכים, הטפסים, הניווט והמסמכים.'}</p></div></section></main>}
function GlobalHeader({screen,me,notifications,children,tasks,accountOpen,setAccountOpen,go,logout,openChild}:{screen:Screen;me:CurrentUserProfile|null;notifications:SmartNotification[];children:DbChild[];tasks:DbTask[];accountOpen:boolean;setAccountOpen:(v:boolean)=>void;go:(s:Screen)=>void;logout:()=>void;openChild:(c:DbChild)=>void}){
 const [query,setQuery]=useState(''); const [notificationOpen,setNotificationOpen]=useState(false); const [profileVisual,setProfileVisual]=useState(()=>({avatar:typeof window!=='undefined'?localStorage.getItem('kidum-avatar-image')||'':'',color:typeof window!=='undefined'?localStorage.getItem('kidum-avatar-color')||'#eaf4ff':'#eaf4ff',name:typeof window!=='undefined'?localStorage.getItem('kidum-display-name')||'':''})); useEffect(()=>{if(me?.avatar_url)setProfileVisual(v=>({...v,avatar:me.avatar_url||v.avatar}));const h=(e:Event)=>{const d=(e as CustomEvent).detail||{};setProfileVisual(v=>({...v,...d}))};window.addEventListener('kidum:profile-updated',h);return()=>window.removeEventListener('kidum:profile-updated',h)},[me?.avatar_url]);
 const title=screen==='home'?'דף הבית':screen==='children'?'הילדים שלי':screen==='tasks'?'משימות':screen==='attention'?'תיעוד והערכות':screen==='notifications'?'התראות':screen==='communications'?'תקשורת':screen==='reports'?'דוחות+':screen==='calendar'?'יומן':screen==='planning'?'תכנון והמלצות':screen==='aiAssistant'?'עוזר AI':screen==='profile'?'החשבון שלי':screen==='archive'?'ארכיון':screen==='progressDashboard'?'התקדמות':screen==='myDocuments'?'המסמכים שלי':screen==='practitionerDirectory'?'ניהול שיבוצים':screen==='practitionerSettings'?'הכרטיס וההגדרות שלי':screen==='regionalHub'?'מרכז שליטה אזורי':screen==='inspectorHub'?'פיקוח ומחוזות':screen==='usersAdmin'?'משתמשים והרשאות':screen==='orgStructure'?'מחוזות, רשויות ומתי״א':screen==='careNetwork'?'מעטפת רב־מקצועית':screen==='parentPortal'?'האזור המשפחתי':screen==='reportTemplates'?'תבניות דוחות':screen==='securityAudit'?'יומן אבטחה':screen==='securitySettings'?'אבטחה וכניסה':screen==='notificationSettings'?'העדפות והתראות':screen==='media'?'ספריית מדיה':screen==='pageEditor'?'עורך גרפי':screen==='reportSetup'?'דוח חדש':screen==='reportEditor'?'עורך דוח':screen==='about'?'אודות':screen==='privacy'?'מדיניות פרטיות':screen==='policy'?'מדיניות שימוש':screen==='terms'?'תנאי שימוש':screen==='accessibility'?'הצהרת נגישות':'קידום+';
 const initial=me?.first_name?.trim()?.[0]||'מ'; const q=query.trim().toLowerCase();
 const dueReminders=tasks.filter(t=>t.reminder_at&&new Date(t.reminder_at).getTime()<=Date.now()&&!['DONE','COMPLETED','ARCHIVED','CANCELLED'].includes(t.status)); const alertCount=notifications.length+dueReminders.length;
 const childHits=q?children.filter(c=>full(c).toLowerCase().includes(q)).slice(0,5):[]; const taskHits=q?tasks.filter(t=>(t.title+' '+(t.description||'')).toLowerCase().includes(q)).slice(0,5):[];
 return <header className="topbar global-topbar"><div className="topbar-page"><b>{title}</b>{screen==='home'&&<span>היום, {new Date().toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long'})}</span>}</div><div className="global-search-wrap"><div className="global-search"><UiIcon name="search" size={19}/><input name="kidum-global-search" autoComplete="off" autoCorrect="off" spellCheck={false} value={query} onChange={e=>setQuery(e.target.value)} placeholder="חיפוש ילדים, משימות, דוחות ועוד..."/></div>{q&&<div className="search-results">{childHits.map(c=><button key={c.id} onClick={()=>{setQuery('');openChild(c)}}><UiIcon name="children" size={18}/><span><b>{full(c)}</b><small>{c.framework_name||'ילד'}</small></span></button>)}{taskHits.map(t=><button key={t.id} onClick={()=>{setQuery('');go('tasks')}}><UiIcon name="tasks" size={18}/><span><b>{t.title}</b><small>משימה</small></span></button>)}{!childHits.length&&!taskHits.length&&<div className="search-none">לא נמצאו תוצאות מתאימות.</div>}</div>}</div><div className="global-account"><div className="global-notification-wrap"><button className="global-bell" aria-label="התראות" aria-expanded={notificationOpen} onClick={()=>{setNotificationOpen(!notificationOpen);setAccountOpen(false)}}><UiIcon name="bell" size={23}/>{alertCount>0&&<i>{alertCount>99?'99+':alertCount}</i>}</button>{notificationOpen&&<><button className="global-popover-backdrop" aria-label="סגירת התראות" onClick={()=>setNotificationOpen(false)}/><div className="global-notification-popover"><div className="notification-popover-head"><div><span>מרכז ההתראות</span><h3>התראות אחרונות</h3></div>{notifications.length>0&&<button onClick={()=>{setNotificationOpen(false);go('notifications')}}>סמן הכול כנקרא</button>}</div><div className="notification-popover-list">{dueReminders.slice(0,3).map((t,i)=><button key={`rem-${t.id}`} onClick={()=>{setNotificationOpen(false);go('tasks')}}><span className={`notification-popover-icon p${i%4}`}><UiIcon name="tasks" size={18}/></span><span><b>תזכורת: {t.title}</b><small>{t.due_at?`מועד יעד ${new Date(t.due_at).toLocaleString('he-IL')}`:'משימה שמחכה לביצוע'}</small></span><time>עכשיו</time></button>)}{notifications.slice(0,Math.max(1,4-dueReminders.length)).map((n,i)=><button key={n.id} onClick={()=>{setNotificationOpen(false);if(n.child_id){const c=children.find(x=>x.id===n.child_id);if(c){openChild(c);return}}const t=String(n.type||'').toLowerCase();go(t.includes('task')?'tasks':t.includes('report')?'reports':t.includes('document')||t.includes('form')?'myDocuments':'notifications')}}><span className={`notification-popover-icon p${i%4}`}><UiIcon name={String(n.type||'').toLowerCase().includes('task')?'tasks':String(n.type||'').toLowerCase().includes('report')?'report':String(n.type||'').toLowerCase().includes('document')?'doc':n.child_id?'children':'bell'} size={18}/></span><span><b>{n.title||'עדכון חדש'}</b><small>{n.body||'יש מידע חדש שמחכה לך במערכת'}</small></span><time>{new Date(n.created_at).toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'})}</time></button>)}{!alertCount&&<div className="notification-popover-empty"><UiIcon name="bell" size={26}/><b>אין התראות חדשות</b><small>הכול מעודכן כרגע</small></div>}</div><button className="notification-popover-all" onClick={()=>{setNotificationOpen(false);go('notifications')}}>לכל ההתראות <UiIcon name="arrow-left" size={16}/></button></div></>}</div><button className="account-trigger" onClick={()=>{setAccountOpen(!accountOpen);setNotificationOpen(false)}} aria-expanded={accountOpen}><span className="avatar account-profile-avatar" style={{'--profile-ring':profileVisual.color} as React.CSSProperties}>{profileVisual.avatar?<img src={profileVisual.avatar} alt="" aria-hidden="true"/>:<b>{initial}</b>}</span><span className="account-text"><b>{me?`${me.first_name} ${me.last_name}`:'משתמש'}</b><small>{me?roleLabel(me.role):'גננת שילוב'}</small></span><span className={`account-chevron ${accountOpen?'open':''}`}><UiIcon name="chevron" size={16}/></span></button>{accountOpen&&<><button className="account-backdrop" aria-label="סגירת תפריט" onClick={()=>setAccountOpen(false)}/><div className="account-menu"><div className="account-menu-head"><span className="avatar account-profile-avatar" style={{'--profile-ring':profileVisual.color} as React.CSSProperties}>{profileVisual.avatar?<img src={profileVisual.avatar} alt="" aria-hidden="true"/>:<b>{initial}</b>}</span><div><b>{me?`${me.first_name} ${me.last_name}`:'משתמש'}</b><small>{me?roleLabel(me.role):'גננת שילוב'}</small></div></div><button onClick={()=>{setAccountOpen(false);go('profile')}}><UiIcon name="user" size={19}/>החשבון שלי</button><button onClick={()=>{setAccountOpen(false);go('securitySettings')}}><UiIcon name="settings" size={19}/>אבטחה וכניסה</button><button onClick={()=>{setAccountOpen(false);go('notificationSettings')}}><UiIcon name="bell" size={19}/>העדפות והתראות</button><button onClick={()=>{setAccountOpen(false);window.dispatchEvent(new Event('kidum:assistant-open'))}}><UiIcon name="ai" size={19}/>עזרה ותמיכה</button><div className="account-menu-sep"/><button className="logout-item" onClick={logout}>יציאה מהמערכת</button></div></>}</div></header>
}
function Nav(p:{children:React.ReactNode;active?:boolean;onClick?:()=>void;icon?:Parameters<typeof UiIcon>[0]['name'];badge?:number}){return <button className={p.active?'nav-item active':'nav-item'} onClick={p.onClick}>{p.icon&&<span className="nav-icon-wrap"><UiIcon name={p.icon} size={22}/>{!!p.badge&&<i className="nav-unread-badge">{p.badge>99?'99+':p.badge}</i>}</span>}<span>{p.children}</span></button>}
function MobileCommunicationsNav({active,onClick}:{active:boolean;onClick:()=>void}){const[count,setCount]=useState(0);useEffect(()=>{let live=true;const pull=async()=>{try{const b:any=await loadCommunications();if(live)setCount(Number(b.unread_sender_count||0))}catch{}};void pull();const t=window.setInterval(pull,10000);const h=()=>void pull();window.addEventListener('kidum:communications-changed',h);return()=>{live=false;window.clearInterval(t);window.removeEventListener('kidum:communications-changed',h)}},[]);return <button className={(active?'active ':'')+'mobile-communications-button'} onClick={onClick}><span className="mobile-communications-icon"><UiIcon name="bell" size={22}/>{count>0&&<i className="mobile-communications-badge">{count>99?'99+':count}</i>}</span><span>תקשורת</span></button>}
function CommunicationsNav({active,onClick}:{active:boolean;onClick:()=>void}){const[count,setCount]=useState(0);useEffect(()=>{let live=true;const pull=async()=>{try{const b:any=await loadCommunications();if(live)setCount(Number(b.unread_sender_count||0))}catch{}};void pull();const t=window.setInterval(pull,10000);const h=()=>void pull();window.addEventListener('kidum:communications-changed',h);return()=>{live=false;window.clearInterval(t);window.removeEventListener('kidum:communications-changed',h)}},[]);return <Nav icon="bell" active={active} onClick={onClick} badge={count}>תקשורת</Nav>} 
function NavGroup({title,icon='doc',active=false,children}:{title:string;icon?:Parameters<typeof UiIcon>[0]['name'];active?:boolean;children:React.ReactNode}){const[open,setOpen]=useState(active);useEffect(()=>{if(active){setOpen(true);window.dispatchEvent(new CustomEvent('kidum:nav-group-open',{detail:title}))}},[active,title]);useEffect(()=>{const h=(e:Event)=>{const opened=(e as CustomEvent<string>).detail;if(opened&&opened!==title)setOpen(false)};window.addEventListener('kidum:nav-group-open',h);return()=>window.removeEventListener('kidum:nav-group-open',h)},[title]);const toggle=()=>setOpen(v=>{const next=!v;if(next)window.dispatchEvent(new CustomEvent('kidum:nav-group-open',{detail:title}));return next});return <div className={`nav-group ${open?'open':''}`}><button className={`nav-group-toggle ${active?'has-active':''}`} onClick={toggle} aria-expanded={open}><UiIcon name={icon} size={20}/><span>{title}</span><svg className="nav-chevron" viewBox="0 0 20 20" aria-hidden="true"><path d="M6.5 8 10 11.5 13.5 8"/></svg></button>{open&&<div className="nav-group-items">{children}</div>}</div>}
