  {miniEdit==='personal'&&<ModalShell title="עריכת פרטים אישיים" close={()=>setMiniEdit(null)}><Field l="תאריך לידה" v={personalDraft.birth_date} s={v=>setPersonalDraft({...personalDraft,birth_date:v})} type="date"/><Field l="מסגרת חינוכית" v={personalDraft.educational_framework} s={v=>setPersonalDraft({...personalDraft,educational_framework:v})}/><label>סוג זכאות</label><select value={personalDraft.entitlement_type} onChange={e=>setPersonalDraft({...personalDraft,entitlement_type:e.target.value})}><option value="">טרם הוגדר</option><option value="INTEGRATION">שילוב</option><option value="PERSONAL">סל אישי</option><option value="INSTITUTIONAL">סל מוסדי</option></select><button className="primary-button" onClick={async()=>{await updateChild(child.id,personalDraft);setMiniEdit(null);reload()}}>שמור פרטים אישיים</button></ModalShell>}
  {miniEdit==='team'&&<ModalShell title={teamEditIndex===null?'הוספת איש צוות':'עריכת איש צוות'} close={()=>setMiniEdit(null)}><div className="team-member-modal-content"><Field l="תפקיד" v={teamDraft.role} s={v=>setTeamDraft({...teamDraft,role:v})}/><Field l="שם איש הצוות" v={teamDraft.name} s={v=>setTeamDraft({...teamDraft,name:v})}/><Field l="טלפון" v={teamDraft.phone} s={v=>setTeamDraft({...teamDraft,phone:v})}/><label>ימי עבודה</label><div className="team-days-picker">{['א׳','ב׳','ג׳','ד׳','ה׳','ו׳'].map(day=>{const days=Array.isArray(teamDraft.days)?teamDraft.days:[];return <button type="button" key={day} className={days.includes(day)?'active':''} onClick={()=>setTeamDraft({...teamDraft,days:days.includes(day)?days.filter((x:string)=>x!==day):[...days,day]})}>{day}</button>})}</div><div className="form-grid"><Field l="שעת התחלה" v={teamDraft.startTime||''} s={v=>setTeamDraft({...teamDraft,startTime:v})} type="time"/><Field l="שעת סיום" v={teamDraft.endTime||''} s={v=>setTeamDraft({...teamDraft,endTime:v})} type="time"/></div><button className="primary-button" disabled={!teamDraft.name||!teamDraft.role} onClick={async()=>{const next=[...(sd.team||[])];if(teamEditIndex===null)next.push(teamDraft);else next[teamEditIndex]=teamDraft;await updateChild(child.id,{support_details:{...sd,team:next}} as any);if(child.followup_start_date)await scheduleChildOnboarding(child.id,{reschedulePending:true}).catch(()=>{});setTeamDraft({role:'',name:'',phone:'',days:[],startTime:'',endTime:''});setTeamEditIndex(null);setMiniEdit(null);reload()}}>{teamEditIndex===null?'הוסף איש צוות':'שמור שינויים'}</button></div></ModalShell>}
  {tab==='overview'&&['ADMIN','MANAGER','COORDINATOR'].includes(role||'')&&<footer className="child-file-footer"><button className="danger-link" onClick={archive}>העברה לארכיון</button></footer>}
