function cleanPlanDomain(v:string){return String(v||'').replace(/^[^\u0590-\u05FF]+/,'').trim()}
function libraryDomainFor(raw:string){const x=cleanPlanDomain(raw);const direct=WORK_PLAN_LIBRARY.find(([d])=>cleanPlanDomain(d)===x||cleanPlanDomain(d).includes(x)||x.includes(cleanPlanDomain(d)))?.[0];if(direct)return direct;const rules:[RegExp,string][]=[[/שפה|תקשור|אוצר מילים|שמיע|פונולוג|כתיב/,'שפה ותקשורת'],[/חבר/,'חברתי'],[/רגש|ויסות/,'ויסות רגשי'],[/קשב|התמדה/,'קשב והתמדה'],[/עדינה|גרפו|גזיר/,'מוטוריקה עדינה'],[/גסה|תנועה|שיווי/,'מוטוריקה גסה'],[/עצמא|יום.?יום|תפקוד/,'עצמאות ותפקודי יום־יום'],[/קוגנ|למיד|מספר|מרחב|זיכרון/,'קוגניטיבי / למידה']];const hit=rules.find(([r])=>r.test(x))?.[1];return WORK_PLAN_LIBRARY.find(([d])=>cleanPlanDomain(d)===hit)?.[0]||null}
function recommendedPlanGoals(scores:Record<string,number>){
 const out:{domain:string;title:string;baseline:number}[]=[];
 for(const [raw,rawScore] of Object.entries(scores||{})){
  const domain=libraryDomainFor(raw); if(!domain)continue;
  const items=(WORK_PLAN_LIBRARY.find(([d])=>d===domain)?.[1]||[]) as readonly string[];
  const score=Math.max(0,Math.min(100,Number(rawScore)||0));
  if(score>=90)continue;
  const start=Math.max(0,Math.min(items.length-1,Math.floor((score/100)*items.length)-2));
  const count=score<35?8:score<60?7:score<75?6:4;
  items.slice(start,Math.min(items.length,start+count)).forEach(title=>out.push({domain:String(domain),title,baseline:score}));
 }
 return out;
}
