 {complianceTab==='requirements'&&<div className="compliance-tab-stack compliance-requirements-list">
 <section className="panel-card compliance-toolbar"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="חיפוש בדרישות, ראיות ופעולות..."/><select value={categoryFilter} onChange={e=>setCategoryFilter(e.target.value)}>{categories.map(c=><option key={c} value={c}>{c==='ALL'?'כל התחומים':c}</option>)}</select><select value={statusFilter} onChange={e=>setStatusFilter(e.target.value as any)}><option value="ALL">כל הסטטוסים</option>{Object.entries(COMPLIANCE_STATUS_LABEL).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></section>{busy?<div className="panel-card"><p>טוען מסמך מוכנות…</p></div>:<section className="compliance-list">{visible.map(x=><article className={`compliance-item status-${x.status.toLowerCase()}`} key={x.id}><header><div><span className="compliance-category">{x.category}</span><h2>{x.title}</h2><p>{x.description}</p></div><div className="compliance-item-controls"><label>סטטוס<select value={x.status} onChange={e=>change(x.id,{status:e.target.value as ComplianceRequirement['status']})}>{Object.entries(COMPLIANCE_STATUS_LABEL).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>עדיפות<select value={x.priority} onChange={e=>change(x.id,{priority:e.target.value as ComplianceRequirement['priority']})}>{Object.entries(COMPLIANCE_PRIORITY_LABEL).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label></div></header><div className="compliance-edit-grid"><label><b>מה כבר בוצע / ראיות</b><textarea value={x.evidence||''} onChange={e=>change(x.id,{evidence:e.target.value})} placeholder="קוד, מסמך, בדיקה, תהליך או ראיה שכבר קיימים…"/></label><label><b>מה עדיין צריך לבצע</b><textarea value={x.next_action||''} onChange={e=>change(x.id,{next_action:e.target.value})} placeholder="הפעולה הבאה הנדרשת כדי לסגור את הדרישה…"/></label></div><footer><span>עודכן: {new Date(x.updated_at).toLocaleString('he-IL')}</span>{x.source_url?<a href={x.source_url} target="_blank" rel="noreferrer">מקור רשמי</a>:null}<button className="primary-button compact" disabled={saving===x.id} onClick={()=>save(x)}>{saving===x.id?'שומר…':'שמור עדכון'}</button></footer></article>)}{!visible.length&&<div className="panel-card"><p>לא נמצאו דרישות התואמות לסינון.</p></div>}</section>}
 </div>}
