 const geoLocalities=(geo?.localities||[]) as any[]; const filteredPractitioners=items.filter((x:any)=>{const assigned=children.filter(c=>(x.child_ids||[]).includes(c.id));const geoRows=assigned.map(c=>geoLocalities.find((z:any)=>z.name===(c.locality||''))).filter(Boolean);return `${x.first_name||''} ${x.last_name||''} ${x.email||''}`.toLowerCase().includes(q.toLowerCase())&&(!districtFilter||geoRows.some((g:any)=>g.district===districtFilter))&&(!authorityFilter||geoRows.some((g:any)=>g.municipality===authorityFilter))&&(!localityFilter||assigned.some(c=>(c.locality||'')===localityFilter))}); const districtOptions=Array.from(new Set(geoLocalities.map((x:any)=>x.district).filter(Boolean))).sort((a:any,b:any)=>String(a).localeCompare(String(b),'he')) as string[]; const authorityOptions=Array.from(new Set(geoLocalities.filter((x:any)=>!districtFilter||x.district===districtFilter).map((x:any)=>x.municipality).filter(Boolean))).sort((a:any,b:any)=>String(a).localeCompare(String(b),'he')) as string[]; const localities=Array.from(new Set(geoLocalities.filter((x:any)=>(!districtFilter||x.district===districtFilter)&&(!authorityFilter||x.municipality===authorityFilter)).map((x:any)=>x.name).filter(Boolean))).sort((a:any,b:any)=>String(a).localeCompare(String(b),'he')) as string[];
