async function exportReportPdfLocal(report:DraftReport,sections:ReportSection[],child:DbChild|null=null,goals:DbGoal[]=[]){
 const html2canvas=(await import('html2canvas')).default;const {PDFDocument}=await import('pdf-lib');
 const host=document.createElement('div');host.dir='rtl';host.style.cssText='position:fixed;left:-10000px;top:0;width:794px;background:#fff;color:#14294d;padding:45px 42px;font-family:Arial, sans-serif;font-size:14px;line-height:1.45;z-index:-1';
 if(isTahiReportName(report.reportTypeName)&&child){host.innerHTML=buildTahiExportHtml(report,sections,child,goals);const st=document.createElement('style');st.textContent=`.tahi-export header{text-align:center;margin-bottom:18px}.tahi-export header h1{font-size:26px;margin:0 0 6px}.tahi-export section{margin:10px 0;break-inside:avoid}.tahi-export h2{display:grid;grid-template-columns:1fr 34px;margin:0 0 8px;background:#eaf3ff;border:1px solid #b9c9db;font-size:16px}.tahi-export h2 span{padding:7px 9px;text-align:right}.tahi-export h2 b{padding:7px;text-align:center;border-right:1px solid #b9c9db}.tahi-export table{width:100%;border-collapse:collapse;table-layout:fixed}.tahi-export th,.tahi-export td{border:1px solid #9eacbb;padding:5px;vertical-align:top;text-align:right;white-space:pre-wrap}.tahi-export thead th{background:#ddebfa}.tahi-export tbody th{background:#f5f8fc}.tahi-export .identity{display:grid;grid-template-columns:repeat(2,1fr);border-top:1px solid #9eacbb;border-right:1px solid #9eacbb}.tahi-export .identity div{display:grid;grid-template-columns:42% 58%;border-left:1px solid #9eacbb;border-bottom:1px solid #9eacbb}.tahi-export .identity b{background:#eaf3ff;padding:5px}.tahi-export .identity span{padding:5px}.tahi-export .long>div{border:1px solid #9eacbb;padding:7px;min-height:65px;margin-top:-1px}.tahi-export .long p{white-space:pre-wrap;margin:7px 0 0}`;host.appendChild(st)}else{const title=document.createElement('h1');title.textContent=`${report.reportTypeName||'דוח'} - קידום+`;title.style.cssText='font-size:30px;text-align:right;margin:0 0 8px';host.appendChild(title);const meta=document.createElement('div');meta.textContent=`גרסה ${report.versionNumber||1} · ${new Date().toLocaleDateString('he-IL')}${report.status==='APPROVED'?'':' · טיוטה'}`;meta.style.cssText='color:#66758c;text-align:right;margin-bottom:28px';host.appendChild(meta);for(const s of sections){const h=document.createElement('h2');h.textContent=s.title;h.style.cssText='font-size:23px;text-align:right;margin:26px 0 10px;border-bottom:1px solid #dbe5f1;padding-bottom:6px';host.appendChild(h);for(const p of s.paragraphs){const el=document.createElement('p');el.textContent=p.text;el.style.cssText='white-space:pre-wrap;text-align:right;margin:0 0 14px';host.appendChild(el)}}}
 document.body.appendChild(host);try{const canvas=await html2canvas(host,{scale:2,backgroundColor:'#ffffff',useCORS:true,logging:false});const pdf=await PDFDocument.create();const pageW=595.28,pageH=841.89,margin=28,usableW=pageW-margin*2,usableH=pageH-margin*2;const pxPerPage=Math.floor(canvas.width*(usableH/usableW));let offset=0;while(offset<canvas.height){const sliceH=Math.min(pxPerPage,canvas.height-offset);const part=document.createElement('canvas');part.width=canvas.width;part.height=sliceH;part.getContext('2d')!.drawImage(canvas,0,offset,canvas.width,sliceH,0,0,canvas.width,sliceH);const png=await pdf.embedPng(part.toDataURL('image/png'));const page=pdf.addPage([pageW,pageH]);const drawH=usableW*(sliceH/canvas.width);page.drawImage(png,{x:margin,y:pageH-margin-drawH,width:usableW,height:drawH});offset+=sliceH}const bytes=await pdf.save();const pdfBuffer=bytes.buffer.slice(bytes.byteOffset,bytes.byteOffset+bytes.byteLength) as ArrayBuffer;downloadBlob(new Blob([pdfBuffer],{type:'application/pdf'}),safeReportFilename(report.reportTypeName,'pdf'))}finally{host.remove()}
}
async function exportReportFile(report:DraftReport,sections:ReportSection[],format:'DOCX'|'PDF',child:DbChild|null=null,goals:DbGoal[]=[]){
 window.dispatchEvent(new CustomEvent('kidum:notice',{detail:format==='DOCX'?'מכין קובץ Word…':'מכין קובץ PDF…'}));
 try{
  if(format==='PDF'){await exportReportPdfLocal(report,sections,child,goals)}else if(isTahiReportName(report.reportTypeName)){await exportReportDocxLocal(report,sections,child,goals)}else{
   try{const result=await exportReportFileCloud(report,sections,format);const a=document.createElement('a');a.href=result.downloadUrl;a.download=result.filename;a.target='_blank';a.rel='noopener';document.body.appendChild(a);a.click();a.remove()}
   catch{await exportReportDocxLocal(report,sections,child,goals)}
  }
  window.dispatchEvent(new CustomEvent('kidum:notice',{detail:format==='DOCX'?'קובץ Word נשמר':'קובץ PDF נשמר'}));
 }catch(e){window.dispatchEvent(new CustomEvent('kidum:notice',{detail:e instanceof Error?`שמירת הקובץ נכשלה: ${e.message}`:'שמירת הקובץ נכשלה'}))}
}

