 const[enabled,setEnabled]=useState(false),[factors,setFactors]=useState<any[]>([]),[enroll,setEnroll]=useState<any|null>(null),[enrollMethod,setEnrollMethod]=useState<'choice'|'sms'|'app'|null>(null),[phone,setPhone]=useState(''),[code,setCode]=useState(''),[policy,setPolicy]=useState<any>({require_mfa:false,session_timeout_minutes:480}),[msg,setMsg]=useState(''),[overview,setOverview]=useState<any|null>(null),[orgUsers,setOrgUsers]=useState<any[]>([]),[recentAudit,setRecentAudit]=useState<SecurityAuditEvent[]>([]),[openAuditId,setOpenAuditId]=useState<string|null>(null),[savingPolicy,setSavingPolicy]=useState(false),[resettingId,setResettingId]=useState<string|null>(null),[enrollBusy,setEnrollBusy]=useState(false);
