 const allDomainItems=()=>{const m=new Map<string,{k:string;q:string}[]>();for(const c of OBSERVATION_CONTEXTS)for(const sec of c.sections){const a=m.get(sec.domain)||[];for(const q of sec.items)a.push({k:`${c.name}::${sec.domain}::${q}`,q});m.set(sec.domain,a)}return m};
 const scoreDomain=(domain:string)=>{const vals=(allDomainItems().get(domain)||[]).map(x=>Number(ratings[x.k])).filter(v=>v>0);return vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):0};
 const scores=()=>Object.fromEntries([...allDomainItems().keys()].map(d=>[d,scoreDomain(d)]).filter(([,v])=>Number(v)>0));
