 const professional=()=>{const sc=scores();const low=Object.entries(sc).filter(([,v])=>Number(v)<70).map(([d])=>cleanPlanDomain(d));const high=Object.entries(sc).filter(([,v])=>Number(v)>=85).map(([d])=>cleanPlanDomain(d));return `התצפית נערכה בסיטואציה: ${context}. ${high.length?`חוזקות בולטות נצפו בתחומים ${high.join(', ')}.`:''} ${low.length?`מומלץ להעמיק ולשקול מטרות בתחומים ${low.join(', ')}.`:'לא עלו בתצפית זו מוקדים משמעותיים המחייבים יעד חדש.'} הסיכום מבוסס על התנהגות שנצפתה בפועל; פריטים שסומנו "לא נצפה" או "לא רלוונטי" אינם מחושבים כקושי.`};
 const save=async(complete:boolean)=>{setBusy(true);try{const row=await saveChildObservation({id:active?.id,childId:child.id,observationType:kind,context,durationMinutes:duration,ratings,notes,domainScores:scores(),domainSummaries:summaries(),professionalSummary:professional(),complete});setActive(row);if(complete&&!row._pending_sync){await upsertAutoDocumentation({childId:child.id,sourceType:'observation',sourceId:row.id,title:kind==='INITIAL'?'תצפית ראשונית':kind==='FINAL'?'תצפית מסכמת':'תצפית מעקב',summary:professional(),occurredAt:row.observed_at,structuredData:{context,duration_minutes:duration,domain_scores:scores(),domain_summaries:summaries(),teacher_note:notes,include_in_plan:true}}).catch(()=>undefined);await refreshTahiFromEvidence(child,{force:true}).catch(()=>undefined)}await refresh();window.dispatchEvent(new Event('kidum:data-invalidated'));window.dispatchEvent(new CustomEvent('kidum:clean'));window.dispatchEvent(new CustomEvent('kidum:notice',{detail:row._pending_sync?'נשמר במכשיר – ממתין לסנכרון אוטומטי':complete?'התצפית הושלמה ונכנסה לתמונת המצב':'טיוטת התצפית נשמרה'}));return true}catch(e){window.dispatchEvent(new CustomEvent('kidum:notice',{detail:e instanceof Error?e.message:'שמירת התצפית נכשלה'}));return false}finally{setBusy(false)}};
